{\frac {\mathrm{d} z _ {i}}{\mathrm{d} \tau}} = {\frac {\partial H}{\partial r _ {i}}}\tag{11.58}

{\frac {\mathrm{d} r _ {i}}{\mathrm{d} \tau}} = {- \frac {\partial H}{\partial z _ {i}}.}\tag{11.59}

